package com.example.demo;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.aot.hint.RuntimeHints;
import org.springframework.aot.hint.RuntimeHintsRegistrar;
import org.springframework.context.annotation.ImportRuntimeHints;

@SpringBootApplication
@ImportRuntimeHints(DemoApp.MyHintsRegistrar.class)
public class DemoApp {

    public static void main(String[] args) {
        SpringApplication.run(DemoApp.class, args);
    }

    static class MyHintsRegistrar implements RuntimeHintsRegistrar {
        @Override
        public void registerHints(RuntimeHints hints, ClassLoader classLoader) {
            // Explicitly register reflection hints for custom payload classes
            hints.reflection().registerType(MyCustomPayload.class, 
                hint -> hint.withMembers(org.springframework.aot.hint.MemberCategory.INVOCABLE_DESTRUCTORS,
                                        org.springframework.aot.hint.MemberCategory.INVOCABLE_CONSTRUCTORS));
        }
    }
}

class MyCustomPayload {
    private String data;
    public String getData() { return data; }
    public void setData(String data) { this.data = data; }
}
